// Inspect and encode generated pixels only; no repainting or alpha masking.
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { sharp } from './sprite-pose-inspector.mjs';

const source='assets/3d/fixed/source/combo-impact-flipbook-v3.png';
const delivery='assets/3d/fixed/combo-impact-flipbook-v3.webp';
const before=await sharp(source).ensureAlpha().raw().toBuffer({resolveWithObject:true});
const {width,height}=before.info,frames=[];
assert.equal(width,height*2,'Four square columns and two rows');
for(let i=0;i<8;i++){
  const x0=Math.round(i%4*width/4),x1=Math.round((i%4+1)*width/4),y0=Math.round(Math.floor(i/4)*height/2),y1=Math.round((Math.floor(i/4)+1)*height/2);
  let left=x1,top=y1,right=x0,bottom=y0,visible=0,boundaryPixels=0;
  for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)if(before.data[(y*width+x)*4+3]>=16){
    visible++;left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x);bottom=Math.max(bottom,y);
    if(x===x0||x===x1-1||y===y0||y===y1-1)boundaryPixels++;
  }
  assert.ok(visible>100,'Frame '+i+' must contain real art');assert.equal(boundaryPixels,0,'Frame '+i+' crosses its cell');
  const gutter=Math.min(left-x0,top-y0,x1-1-right,y1-1-bottom);
  assert.ok(gutter>=12,'Frame '+i+' needs a transparent gutter');
  frames.push({frame:i,cell:{left:x0,top:y0,width:x1-x0,height:y1-y0},visibleBounds:{left,top,width:right-left+1,height:bottom-top+1},visiblePixels:visible,minimumTransparentGutter:gutter,boundaryPixels});
}
await sharp(source).webp({lossless:true,effort:6}).toFile(delivery);
const after=await sharp(delivery).ensureAlpha().raw().toBuffer({resolveWithObject:true});
assert.equal(after.info.width,width);assert.equal(after.info.height,height);
let alphaDifferences=0,visibleRgbDifferences=0;
for(let i=0;i<before.data.length;i+=4){
  if(before.data[i+3]!==after.data[i+3])alphaDifferences++;
  if(before.data[i+3]>0)for(let c=0;c<3;c++)if(before.data[i+c]!==after.data[i+c])visibleRgbDifferences++;
}
assert.equal(alphaDifferences,0);assert.equal(visibleRgbDifferences,0);
const result={date:'2026-10-11',source,delivery,width,height,frames,alphaDifferences,visibleRgbDifferences,lossless:true,bytes:(await fs.stat(delivery)).size};
const pivots=frames.map(f=>({x:+((f.visibleBounds.left+f.visibleBounds.width/2-f.cell.left)/f.cell.width).toFixed(6),y:+((f.visibleBounds.top+f.visibleBounds.height/2-f.cell.top)/f.cell.height).toFixed(6)}));
await fs.writeFile('src/3d/combo-impact-data.js','// Generated by tools/combo-impact-assets.mjs; original pixels are unchanged.\nexport const COMBO_IMPACT_PIVOTS = '+JSON.stringify(pivots)+';\n');
await fs.writeFile('docs/COMBO_IMPACT_ASSET_VALIDATION.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(result,null,2));
